PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "role" varchar not null default 'pet_owner', "provider_type" varchar, "phone" varchar, "bio" text, "avatar" varchar, "is_verified" tinyint(1) not null default '0', "latitude" numeric, "longitude" numeric, "certification" varchar, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "is_active" tinyint(1) not null default '1');
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "pets" ("id" integer primary key autoincrement not null, "user_id" integer not null, "name" varchar not null, "type" varchar not null, "breed" varchar, "age" integer not null, "weight" numeric, "photo" varchar, "health_notes" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "addresses" ("id" integer primary key autoincrement not null, "user_id" integer not null, "label" varchar not null, "address_line" text not null, "city" varchar not null, "latitude" numeric, "longitude" numeric, "is_primary" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "services" ("id" integer primary key autoincrement not null, "provider_id" integer, "name" varchar not null, "description" text, "price" numeric not null, "duration_minutes" integer not null default '60', "provider_type" varchar, "created_at" datetime, "updated_at" datetime, foreign key("provider_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "products" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "name" varchar not null, "description" text, "price" numeric not null, "stock" integer not null default '0', "image" varchar, "created_at" datetime, "updated_at" datetime, foreign key("seller_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "provider_schedules" ("id" integer primary key autoincrement not null, "user_id" integer not null, "day_of_week" integer not null, "start_time" time not null, "end_time" time not null, "is_available" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "bookings" ("id" integer primary key autoincrement not null, "pet_owner_id" integer not null, "provider_id" integer not null, "pet_id" integer not null, "service_id" integer, "booking_date" date not null, "start_time" time not null, "status" varchar not null default 'pending', "total_price" numeric not null, "address_id" integer, "notes" text, "completion_notes" text, "created_at" datetime, "updated_at" datetime, foreign key("pet_owner_id") references "users"("id") on delete cascade, foreign key("provider_id") references "users"("id") on delete cascade, foreign key("pet_id") references "pets"("id") on delete cascade, foreign key("service_id") references "services"("id") on delete set null, foreign key("address_id") references "addresses"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "medical_records" ("id" integer primary key autoincrement not null, "pet_id" integer not null, "vet_id" integer not null, "booking_id" integer, "visit_date" date not null, "diagnosis" text not null, "treatment" text not null, "recommendation" text, "notes" text, "pdf_path" varchar, "created_at" datetime, "updated_at" datetime, foreign key("pet_id") references "pets"("id") on delete cascade, foreign key("vet_id") references "users"("id") on delete cascade, foreign key("booking_id") references "bookings"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "reviews" ("id" integer primary key autoincrement not null, "booking_id" integer, "pet_owner_id" integer not null, "provider_id" integer not null, "rating" integer not null, "comment" text, "created_at" datetime, "updated_at" datetime, foreign key("booking_id") references "bookings"("id") on delete set null, foreign key("pet_owner_id") references "users"("id") on delete cascade, foreign key("provider_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "orders" ("id" integer primary key autoincrement not null, "pet_owner_id" integer not null, "status" varchar not null default 'pending', "total_amount" numeric not null, "shipping_address" text not null, "payment_proof" varchar, "created_at" datetime, "updated_at" datetime, foreign key("pet_owner_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "order_items" ("id" integer primary key autoincrement not null, "order_id" integer not null, "product_id" integer not null, "quantity" integer not null, "price" numeric not null, "created_at" datetime, "updated_at" datetime, foreign key("order_id") references "orders"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "roles" ("id" integer primary key autoincrement not null, "name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "role_user" ("id" integer primary key autoincrement not null, "role_id" integer not null, "user_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("role_id") references "roles"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "roles_name_unique" on "roles" ("name");
CREATE UNIQUE INDEX "role_user_role_id_user_id_unique" on "role_user" ("role_id", "user_id");
COMMIT;
